// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(address, bytes calldata data) public {
        Reverter reverter = new Reverter();
        vm.prank(address(this));
        (bool success, ) = address(c).call(abi.encodeWithSignature("forward(address,bytes)", address(reverter), data));
        assertTrue(!success, "forward must revert when callee reverts");
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
